                    {
                        "control": "3.1",
                        "description": "Keep cardholder data storage to a minimum by implementing data retention and disposal policies, procedures and processes."
                    },
                    {
                        "control": "3.4",
                        "description": "Render Primary Account Numbers (PAN) unreadable anywhere it is stored (including on portable digital media, backup media, and in logs).If you use an S3 bucket to store credit card Primary Account Numbers (PAN), then to render the PAN unreadable, the bucket default encryption should be enabled and/or the S3 bucket policy should explicitly deny put-object requests without server-side encryption."
                    },
                    {
                        "control": "3.5",
                        "description": "Document and implement procedures to protect keys used to secure stored cardholder data against disclosure and misuse"
                    },
                    {
                        "control": "4.1",
                        "description": "Use strong cryptography and security protocols to safeguard sensitive cardholder data during transmission over open, public networks."
                    },
                    {
                        "control": "7.1",
                        "description": "Limit access to system components and cardholder data to only those individuals whose job requires such access."
                    },
                    {
                        "control": "7.2",
                        "description": "Establish an access control system(s) for systems components that restricts access based on a user’s need to know, and is set to “deny all” unless specifically allowed."
                    },
                    {
                        "control": "8.3.2",
                        "description": "Incorporate multi-factor authentication for all non-console access into the CDE for personnel with administrative access."
                    },
                    {
                        "control": "10.1",
                        "description": "Implement audit trails to link all access to system components to each individual user."
                    }
