            }
        ],
        "regulation_meta": [
            {
                "citation_meta": [
                    {
                        "citation": "1798.100(e)",
                        "description": "General Duties of Businesses that Collect Personal Information: A business that collects a consumer’s personal information shall implement reasonable security procedures and practices appropriate to the nature of the personal information to protect the personal information from unauthorized or illegal access, destruction, use, modification, or disclosure in accordance with Section 1798.81.5."
                    },
                    {
                        "citation": "1798.150(a)(1)",
                        "description": "Any consumer whose nonencrypted and nonredacted personal information, as defined in subparagraph (A) of paragraph (1) of subdivision (d) of Section 1798.81.5, is subject to an unauthorized access and exfiltration, theft, or disclosure as a result of the business’s violation of the duty to implement and maintain reasonable security procedures and practices appropriate to the nature of the information to protect the personal information may institute a civil action."
                    }
                ],
                "regulation": "CCPA",
                "has_standards": true
            },
            {
                "citation_meta": [
                    {
                        "citation": "5.1(f)",
                        "description": "Personal data shall be processed in a manner that ensures appropriate security of the personal data, including protection against unauthorised or unlawful processing and against accidental loss, destruction or damage, using appropriate technical or organisational measures (‘integrity and confidentiality’)."
                    },
                    {
                        "citation": "32.1(a)",
                        "description": "the controller and the processor shall implement appropriate technical and organisational measures to ensure a level of security appropriate to the risk, including inter alia as appropriate: the pseudonymisation and encryption of personal data"
                    },
                    {
                        "citation": "32.1(b)",
                        "description": "the controller and the processor shall implement appropriate technical and organisational measures to ensure a level of security appropriate to the risk, including inter alia as appropriate: the ability to ensure the ongoing confidentiality, integrity, availability and resilience of processing systems and services"
                    },
                    {
                        "citation": "32.2",
                        "description": "In assessing the appropriate level of security account shall be taken in particular of the risks that are presented by processing, in particular from accidental or unlawful destruction, loss, alteration, unauthorised disclosure of, or access to personal data transmitted, stored or otherwise processed."
                    },
                    {
                        "citation": "34.3(a)",
                        "description": "The communication to the data subjec shall not be required if any of the following conditions are met: the controller has implemented appropriate technical and organisational protection measures, and those measures were applied to the personal data affected by the personal data breach, in particular those that render the personal data unintelligible to any person who is not authorised to access it, such as encryption"
                    },
                    {
                        "citation": "39",
                        "description": "Personal data should be processed in a manner that ensures appropriate security and confidentiality of the personal data, including for preventing unauthorised access to or use of personal data and the equipment used for the processing."
                    },
                    {
                        "citation": "25",
                        "description": "Data protection by design and by default \nThe controller shall implement appropriate technical and organisational measures for ensuring that, by default, only personal data which are necessary for each specific purpose of the processing are processed. 2That obligation applies to the amount of personal data collected, the extent of their processing, the period of their storage and their accessibility. 3In particular, such measures shall ensure that by default personal data are not made accessible without the individual’s intervention to an indefinite number of natural persons."
                    },
                    {
                        "citation": "46",
                        "description": "Transfers subject to appropriate safeguards \nIn the absence of a decision pursuant to Article 45(3), a controller or processor may transfer personal data to a third country or an international organisation only if the controller or processor has provided appropriate safeguards, and on condition that enforceable data subject rights and effective legal remedies for data subjects are available."
                    }
                ],
                "regulation": "GDPR",
                "has_standards": true
            },
            {
                "citation_meta": [
                    {
                        "citation": "Article 46",
                        "description": "Processing agents shall adopt security, technical and administrative measures able to protect personal data from unauthorized accesses and accidental or unlawful situations of destruction, loss, alteration, communication or any type of improper or unlawful processing."
                    },
                    {
                        "citation": "Article 16",
                        "description": "Personal data will be eliminated after the end of its processing, within the scope and the technical limits of the activities"
                    }
                ],
                "regulation": "BR LGPD",
                "has_standards": false
            },
            {
                "citation_meta": [
                    {
                        "citation": "4.7.3",
                        "description": "The methods of protection should include\n (a) physical measures, for example, locked filing cabinets and restricted access to offices;\n(b) organizational measures, for example, security clearances and limiting access on a “need-to-know” basis; and\n(c) technological measures, for example, the use of passwords and encryption."
                    }
                ],
                "regulation": "PIPEDA",
                "has_standards": false
            }
        ]
    }
